// Reads commands stored in matching files. Running npx vitest -u directly in a terminal leaves no source for this check, and terminal text is not parsed. Only the named runner spellings are covered; wrapper commands and environment-variable behavior such as CI=false are missed. A deliberate regeneration and a blind one carry the same update flag, so the source pattern alone cannot establish whether snapshots were reviewed.
import { checkSource, liveSource } from '../source.mjs';

const spec = {
  "id": "javascript-typescript.snapshot-updated-wholesale",
  "title": "Snapshots regenerated by a committed command instead of reviewed",
  "paths": [
    ".github/workflows/*.yml",
    ".github/workflows/*.yaml",
    ".gitlab-ci.yml",
    "**/package.json",
    "**/Makefile",
    "**/*.sh"
  ],
  "patterns": [
    "\\b(?:vitest|jest)\\b[^\\n]{0,120}?(?:\\s-u|\\s--update(?:-snapshots?|Snapshot)?)(?!\\w)"
  ],
  "stripComments": true,
  "stripStrings": false,
  "perLine": false,
  "commentSyntax": {
    ".js": "slash",
    ".mjs": "slash",
    ".cjs": "slash",
    ".jsx": "slash",
    ".ts": "slash",
    ".mts": "slash",
    ".cts": "slash",
    ".tsx": "slash"
  }
};
export const id = spec.id;
export const what = spec.title;
export const check = (context) => checkSource(context, spec);
export const live = (context) => liveSource(context, spec);
